import{_ as t,o,c as r,a2 as a}from"./chunks/framework.BN3Eol-0.js";const s="/orrery/docs/assets/locale-ja.DGVbCNAn.png",n="/orrery/docs/assets/01-explore.DD4mN_o_.png",i="/orrery/docs/assets/20-explore-in-the-sky.DbJtBI9x.png",l="/orrery/docs/assets/02-plan.DzQ0bKiD.png",c="/orrery/docs/assets/13-mission-sandbox.BCL-4WGi.png",d="/orrery/docs/assets/03-fly-curiosity.CSvpLJb0.png",h="/orrery/docs/assets/03-fly-apollo11.BVNyTH9w.png",p="/orrery/docs/assets/19-fly-launch-director.CA02VHla.png",g="/orrery/docs/assets/12-flight-director.BX4knbKT.png",u="/orrery/docs/assets/04-missions.COdVmeTU.png",m="/orrery/docs/assets/mission-panel.0Tri57u-.png",y="/orrery/docs/assets/18-launches-catalogue.D17QluNY.png",f="/orrery/docs/assets/17-programs-catalogue.CvuVy7es.png",b="/orrery/docs/assets/16-fleet-catalogue.BsMoERzv.png",w="/orrery/docs/assets/05-earth.Bs1f_Gdo.png",v="/orrery/docs/assets/06-moon.UR7zFkOw.png",k="/orrery/docs/assets/22-moon-traverse.CnhzWq2U.png",S="/orrery/docs/assets/07-mars.CdK3wk1P.png",A="/orrery/docs/assets/08-iss.KhxuUjVD.png",E="/orrery/docs/assets/11-science-lens-iss.B71zFh--.png",L="/orrery/docs/assets/09-tiangong.CVV-aoet.png",T="/orrery/docs/assets/10-science-landing.Bwqhm83u.png",R="/orrery/docs/assets/10-science-section.BfKU2q1L.png",C="/orrery/docs/assets/21-gallery.B1Qm8Csv.png",x="/orrery/docs/assets/14-credits.BK6fVVSz.png",P="/orrery/docs/assets/15-library.CVT_W0XH.png",G=JSON.parse('{"title":"User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guides/user-guide.md","filePath":"guides/user-guide.md"}'),I={name:"guides/user-guide.md"};function D(M,e,N,O,_,q){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="user-guide" tabindex="-1">User Guide <a class="header-anchor" href="#user-guide" aria-label="Permalink to &quot;User Guide&quot;">​</a></h1><p><em>Orrery — read-this-first guide for the live app · 0.9.9 · November 2026</em></p><blockquote><p>Every screenshot in this guide is the app at 1280×800 in English (the language shots are the exceptions). Click any image to open it full-size in a new tab.</p></blockquote><h2 id="finding-your-way-around" tabindex="-1">Finding your way around <a class="header-anchor" href="#finding-your-way-around" aria-label="Permalink to &quot;Finding your way around&quot;">​</a></h2><p>The navigation bar reads, left to right: <strong>HOME · EXPLORE · WORLDS · FLY · PLAN · CATALOG · LEARN</strong>. EXPLORE, WORLDS, CATALOG and LEARN open a menu; each also has a hub page of its own (<code>/explore/hub</code>, <code>/worlds</code>, <code>/catalog</code>, <code>/learn</code>) with a card per destination.</p><table tabindex="0"><thead><tr><th>Group</th><th>What is in it</th></tr></thead><tbody><tr><td><strong>EXPLORE</strong></td><td><code>/explore</code> — one level per scale, from the solar system out to the cosmic web</td></tr><tr><td><strong>WORLDS</strong></td><td><code>/earth</code>, <code>/moon</code>, <code>/mars</code>, <code>/venus</code> — the worlds you can stand on</td></tr><tr><td><strong>FLY</strong>, <strong>PLAN</strong></td><td><code>/fly</code> the mission arc, <code>/plan</code> the porkchop mission configurator</td></tr><tr><td><strong>CATALOG</strong></td><td><code>/programs</code>, <code>/missions</code> (+ <code>/missions/launches</code>), <code>/fleet</code>, <code>/iss</code>, <code>/tiangong</code>, <code>/live</code></td></tr><tr><td><strong>LEARN</strong></td><td><code>/essays</code>, <code>/science</code>, <code>/lab</code></td></tr><tr><td><strong>Footer</strong></td><td>Gallery (deep-sky, posters, insignia), Credits, Colophon, Library, Glossary, About</td></tr></tbody></table><hr><hr><h2 id="on-your-phone" tabindex="-1">On your phone <a class="header-anchor" href="#on-your-phone" aria-label="Permalink to &quot;On your phone&quot;">​</a></h2><p>Orrery is <strong>mobile-first</strong> — every route adapts to a phone: a hamburger nav, bottom-sheet panels, and touch gestures on the 3D scenes (one-finger drag to orbit, <strong>pinch to zoom</strong>, tap to select).</p><ul><li><strong>Native apps (iOS + Android)</strong> are in progress (v0.8) — a Capacitor wrapper of this same web app, headed for the App Store + Google Play. Same experience, installed from a store, with a native share sheet and offline core.</li><li><strong>Right now</strong> you can install the web app as a PWA: open the site in your phone browser and use &quot;Add to Home Screen&quot; (Android Chrome offers an install prompt; iOS Safari → Share → Add to Home Screen).</li></ul><p>The rest of this guide describes the app screen-by-screen — it reads the same on desktop and phone.</p><hr><h2 id="switching-language" tabindex="-1">Switching language <a class="header-anchor" href="#switching-language" aria-label="Permalink to &quot;Switching language&quot;">​</a></h2><p>A locale picker sits in the top-right of the navigation bar. The chip shows the locale&#39;s short tag (e.g. <code>DE</code>). Click it to open the dropdown, pick your language, and the URL updates to the locale-prefixed path (e.g. <code>/de/…</code>). Bookmark the URL to lock your locale; share it and your reader gets the same. (Flag emoji were dropped — they render inconsistently across platforms; the short tag is unambiguous everywhere.)</p><p>The URL is the main place your locale lives; the only thing stored is a small functional cookie (<code>orrery_locale</code>), written <em>only</em> when you click a locale chip (see <a href="#privacy">Privacy</a>). On a fresh visit the browser language is sniffed (<code>navigator.language</code>) and applied automatically; if it doesn&#39;t match a supported locale, English is the default.</p><p><a href="screenshots/locale-ja.png"><img src="'+s+'" alt="Japanese locale"></a></p><p><strong>Currently shipped — 14 languages, all at 100% UI parity:</strong></p><table tabindex="0"><thead><tr><th>Locale</th><th>Native name</th><th>Notes</th></tr></thead><tbody><tr><td><code>en-US</code></td><td>English</td><td>Source language</td></tr><tr><td><code>es</code></td><td>Español</td><td>First non-English locale (v0.3.0)</td></tr><tr><td><code>fr</code></td><td>Français</td><td></td></tr><tr><td><code>de</code></td><td>Deutsch</td><td></td></tr><tr><td><code>pt-BR</code></td><td>Português (BR)</td><td></td></tr><tr><td><code>it</code></td><td>Italiano</td><td></td></tr><tr><td><code>nl</code></td><td>Nederlands</td><td>Added v0.5.x (issue #72)</td></tr><tr><td><code>zh-CN</code></td><td>中文 (简体)</td><td></td></tr><tr><td><code>ja</code></td><td>日本語</td><td></td></tr><tr><td><code>ko</code></td><td>한국어</td><td></td></tr><tr><td><code>hi</code></td><td>हिन्दी</td><td>Devanagari</td></tr><tr><td><code>ar</code></td><td>العربية</td><td>RTL — flips the entire layout</td></tr><tr><td><code>ru</code></td><td>Русский</td><td>Cyrillic</td></tr><tr><td><code>sr-Cyrl</code></td><td>Српски</td><td>Serbian Cyrillic</td></tr></tbody></table><p>The <code>/science</code> encyclopedia overlay tree is translated end-to-end across <strong>all 14 locales</strong>. Editorial entity overlays (missions, planets, sites, modules) are translated across all 14 locales for the v0.5.x rollout.</p><hr><h2 id="solar-system-explorer-·-explore" tabindex="-1">Solar System Explorer · <code>/explore</code> <a class="header-anchor" href="#solar-system-explorer-·-explore" aria-label="Permalink to &quot;Solar System Explorer · `/explore`&quot;">​</a></h2><p>A real-time 3D / 2D orrery in <strong>eight nested scales</strong>: Solar System · Stellar Neighborhood · Milky Way · Local Group · Local Sheet · Virgo Supercluster · Laniakea · Cosmic Web. The solar-system scale shows 8 planets, 5 dwarf planets, 2 comets, and ʻOumuamua (the only confirmed interstellar object).</p><p><a href="screenshots/01-explore.png"><img src="'+n+'" alt="Explorer screenshot"></a></p><p><strong>Moving between scales</strong>:</p><ul><li><strong>Zoom in or out</strong> — the scene passes through the eight scales as you scroll or pinch — or use the <strong>level picker</strong> (top right) and the <strong>back</strong> button.</li><li><strong>One scale bar</strong> (bottom right) reads in KM · AU · LY · PC; click a unit to switch.</li><li><strong>INDEX</strong> (the tab on the left edge) opens the same panel at every scale: every selectable object of the scene, a search box, kind chips, and a ↗ on every object that has a page of its own. Picking a row selects and focuses the object.</li><li><strong>ORBIT RULER</strong> (bottom left) lists the orbit regimes of the scale (Oort cloud in to the Sun on the solar-system scale); each row draws its own band.</li></ul><p><strong>What you can do</strong>:</p><ul><li><strong>Drag</strong> the 3D scene to orbit around the Sun.</li><li><strong>Scroll</strong> / <strong>pinch</strong> to zoom.</li><li><strong>Click any body</strong> — Sun, planet, dwarf, comet, ʻOumuamua — to open its detail panel with <strong>OVERVIEW · GALLERY · TECHNICAL · MISSIONS</strong> tabs.</li><li><strong>Hover</strong> in 3D for a velocity tooltip (mean orbital velocity via vis-viva).</li><li><strong><code>2D</code> toggle</strong> (top right) — switches to a top-down 2D plot of the ecliptic plane.</li><li><strong><code>REFERENCES · PLANET SCALES</code></strong> (bottom left) — opens a true-relative-size diorama of the planets.</li><li><strong>Chip row</strong> (top left) — ICONIC MISSIONS · PLANETS · DWARFS · COMETS · ISM show / hide each group independently. Hidden bodies aren&#39;t clickable, and turning a chip off clears a selection inside it.</li><li><strong>Time dock</strong> (bottom) — pause, 1× / 10× / 100× speed, and the date.</li><li><strong>Stars and deep-sky objects</strong> open a panel with <strong>OVERVIEW</strong> and <strong>IN THE SKY</strong> tabs. IN THE SKY draws the object&#39;s constellation as a line figure with the object marked, and prints its constellation, position, the nearest bright star (within 15°), the best months to see it, how high it climbs from your latitude (taken from your browser&#39;s time zone — no permission prompt), and what shows it: naked eye, binoculars, or a telescope. Every number is computed from the object&#39;s own RA / Dec and magnitude; the Sun&#39;s position for the best-months rule comes from NASA JPL Horizons.</li></ul><p><a href="screenshots/20-explore-in-the-sky.png"><img src="'+i+'" alt="Deep-sky panel, IN THE SKY tab"></a></p><p><strong>Turn on the Science Lens</strong> (the lens icon in the nav) and the scene becomes a textbook layer (the <a href="#iss-explorer-iss">ISS section</a> shows it on a station scene).</p><p>A <strong>Science Lens banner</strong> above the canvas explains the current view in plain language; a <strong>Science Layers panel</strong> lets you toggle individual physics layers (gravity vectors, velocity vectors, centripetal arrows, apsides + true anomaly, sphere-of-influence rings, hover info cards). Layer values print at arrow tips so you can compare magnitudes across planets.</p><hr><h2 id="mission-configurator-·-plan" tabindex="-1">Mission Configurator · <code>/plan</code> <a class="header-anchor" href="#mission-configurator-·-plan" aria-label="Permalink to &quot;Mission Configurator · `/plan`&quot;">​</a></h2><p>The Lambert porkchop plot. Pick a destination + mission type (LANDING or FLYBY). The destination menu has 22 destinations in five groups — Inner system (Moon, Mercury, Venus, Mars, Phobos, Deimos), Asteroids (Vesta, Ceres, Psyche, Bennu), Jupiter system (Jupiter, Io, Europa, Ganymede, Callisto), Saturn system (Saturn, Titan, Enceladus) and Outer system (Uranus, Neptune, Triton, Pluto); a planetary moon flies its host planet&#39;s arc with the moon named as the target. Each destination uses a <strong>pre-computed</strong> 112×100 grid (11,200 cells) checked in at <code>static/data/porkchop/</code> and loaded by the app at runtime — the Lambert <strong>Web Worker</strong> stays in the bundle for future custom-range work but is <strong>not</strong> what paints the default Mercury–Pluto maps. Deep-blue cells are the cheap launch windows; red cells are expensive.</p><p><a href="screenshots/02-plan.png"><img src="'+l+'" alt="Porkchop screenshot"></a></p><p><strong>What you can do</strong>:</p><ul><li><strong>Click any cell</strong> to read the exact dep / arr dates, transit, and ∆v.</li><li><strong>Pick a vehicle</strong> from 13 launch rockets — the panel computes vehicle ∆v vs required ∆v and shows margin or deficit.</li><li><strong>▶ FLY MISSION</strong> — opens <code>/fly</code> with your selected destination, dep / arr dates and rocket baked into the URL (<code>/fly?dest&amp;type&amp;dep&amp;tof&amp;rocket</code>); it is enabled only while the rocket&#39;s ∆v budget holds. The rocket you picked is the vehicle the flight shows and the one that launches.</li><li><strong>Mobile</strong>: long-press the porkchop for a magnifier loupe.</li></ul><p><strong>Mission Sandbox</strong> (lens on or off — always available): pin one cell with <code>📌 PIN THIS CELL</code>, then click another cell. The compare panel shows ΔDEP, ΔTOF, and Δ∆v (green chip when the new cell is cheaper, gold when more expensive). Pin clears automatically when you change destination.</p><p><a href="screenshots/13-mission-sandbox.png"><img src="'+c+'" alt="Mission Sandbox compare panel"></a></p><hr><h2 id="mission-arc-·-fly" tabindex="-1">Mission Arc · <code>/fly</code> <a class="header-anchor" href="#mission-arc-·-fly" aria-label="Permalink to &quot;Mission Arc · `/fly`&quot;">​</a></h2><p>The mission visualisation. Earth, the destination, and the spacecraft animate live; the trajectory tube uses a true two-point Keplerian ellipse with Sun at focus, so both endpoints lock to live planet positions.</p><p><a href="screenshots/03-fly-curiosity.png"><img src="'+d+'" alt="Curiosity flight"></a></p><p><strong>What you can do</strong>:</p><ul><li><strong>Scrub the timeline</strong> — bottom bar — to fly the mission from launch to arrival.</li><li><strong>▶ / ⏸ + speed pills</strong> — autoplay at 1× / 7× / 30× / 90× (Mars-class missions) or 0.1× / 0.5× / 1× / 3× (lunar).</li><li><strong><code>2D</code> toggle</strong> — switch between the 3D scene and a top-down 2D view.</li><li><strong>CAPCOM panel</strong> (right) — live mission events (TLI, TCM, EDL, etc.) tick by as you scrub.</li><li><strong>Pre-built missions</strong>: try <code>/fly?mission=&lt;id&gt;</code> for any of the 141 missions in the catalog.</li><li><strong>The briefing card</strong>: every flight opens on a card with the mission&#39;s photo, story, vehicle, payload, ∆v and transit, the fleet craft it flew, and three buttons — <strong>START WITH LAUNCH</strong> (the ascent from the pad), <strong>SKIP TO LANDING</strong> (the descent, where the mission has one) and <strong>PROCEED TO SIMULATION</strong> (the cruise).</li><li><strong>Play bar and markers</strong>: one marker row carries the whole journey — ascent beats (liftoff, MAX-Q, stage separation, fairing, SECO, parking orbit, injection burn), cruise milestones (gold dots), Flight Director stages (gold diamonds) and descent beats where a profile exists. Click a marker to seek there.</li><li><strong>Phase markers</strong> appear on every mission with timeline events — click any marker dot to jump the sim to that event&#39;s MET (LOI, TCM, descent, arrival, EDL). Each marker carries a science-chip linking to the matching <code>/science</code> encyclopedia section. Keyboard-focusable + screen-reader-readable. Reduced-motion: snap, no animation.</li><li><strong>Lunar missions</strong> (Apollo, Artemis II, Blue Moon, Chang&#39;e, Chandrayaan, Luna, SLIM) auto-open in a dedicated <strong>cislunar view</strong> (ADR-058) anchored at Earth, rendering each mission&#39;s actual flight architecture — Apollo free-return figure-8 with parking orbit + lunar orbit + descent, Artemis II hybrid free-return at 9 200 km periselene, Chandrayaan-3 multi-burn Earth spiral + lunar spiral + descent, Chang&#39;e 5 lunar-orbit-rendezvous sample-return, etc. The camera zooms in as the spacecraft approaches the Moon and pulls back as it leaves.</li><li><strong>Mars + outer-system missions</strong> render the heliocentric transfer arc (Earth → target body) via <code>flight.interplanetary_profile</code> waypoints (ADR-058 third amendment), with the same phase-marker overlay + science chips as Moon missions. Mariner 4 (1964) through Hope Probe (2020), Voyager 2&#39;s Grand Tour flybys, New Horizons&#39; Jupiter assist + Pluto + Arrokoth, Dawn&#39;s Vesta-then-Ceres.</li></ul><p><a href="screenshots/03-fly-apollo11.png"><img src="'+h+'" alt="Apollo 11 fly"></a></p><p><strong>The launch.</strong> START WITH LAUNCH plays the ascent under a <strong>seeded camera director</strong>: the same launch always replays the same shots, and different launches differ (the seed is the vehicle and the mission). The first seconds are a vertical rise; the scene draws the <strong>real pad</strong> of the launch site and year — the Apollo launch umbilical tower, the Shuttle service structures, the Soviet R-7 and Proton pads, the Falcon transporter-erector, the SLS mobile launcher — built to scale against the vehicle, with moving parts (swing arms, support arms, the strongback) tied to the mission clock, so scrubbing never jumps. The light follows the <strong>real launch time</strong> at the pad when the data has one (night, dusk, golden hour or midday, with cloud and pad smoke); a flight without a recorded time is seeded. Append <code>?cam=classic</code> for the old fixed camera. With reduced motion on, the director uses hard cuts.</p><p><a href="screenshots/19-fly-launch-director.png"><img src="'+p+'" alt="Launch of Apollo 11 from LC-39A under the camera director"></a></p><p><strong>The 2D view</strong> fits the flight: it draws only the destination (and, for a planetary moon, its host), keeps one scale for the whole flight and shows a 1 AU bar.</p><p><strong>Turn on the Science Lens</strong> for the <strong>Flight Director banner</strong> — a 5-phase narration that flips through the mission as you scrub:</p><p><a href="screenshots/12-flight-director.png"><img src="'+g+'" alt="Flight Director on /fly"></a></p><table tabindex="0"><thead><tr><th>Phase</th><th>What it explains</th></tr></thead><tbody><tr><td><strong>DEPARTURE</strong></td><td>C3 launch energy, leaving Earth&#39;s gravity well</td></tr><tr><td><strong>TRANS-X INJECTION</strong></td><td>The biggest single ∆v of the trip — TLI for Moon, TMI for Mars</td></tr><tr><td><strong>CRUISE</strong></td><td>The Hohmann transfer ellipse, vis-viva at every point</td></tr><tr><td><strong>APPROACH</strong></td><td>V∞ excess speed, minimum braking ∆v before insertion</td></tr><tr><td><strong>ARRIVAL</strong></td><td>Hyperbolic capture into a closed orbit</td></tr></tbody></table><p>Each phase title is a deep link into the matching <code>/science</code> chapter. The lens also unlocks a <strong>Conic-section side panel</strong> in the bottom-right that classifies the current arc shape (circle / ellipse / parabola / hyperbola) live from specific orbital energy.</p><hr><h2 id="mission-catalog-·-missions" tabindex="-1">Mission Catalog · <code>/missions</code> <a class="header-anchor" href="#mission-catalog-·-missions" aria-label="Permalink to &quot;Mission Catalog · `/missions`&quot;">​</a></h2><p>All 141 missions in the dataset, 1957 to 2031: Earth orbit (46), Moon (37), Mars (24), Venus (6), Jupiter (5), Saturn (4), Mercury (3), the Sun (3), and comets, asteroids, Neptune and Pluto, from Sputnik 1 to Starship Mars Crew (concept). The page was previously called &quot;Mission Library&quot;; it was renamed to <strong>Mission Catalog</strong> under <a href="./../adr/ADR-051">ADR-051</a> to free the word <em>Library</em> for the outbound-link inventory at <code>/library</code>.</p><p><a href="screenshots/04-missions.png"><img src="'+u+'" alt="Catalog"></a></p><h3 id="the-catalogue-pattern" tabindex="-1">The catalogue pattern <a class="header-anchor" href="#the-catalogue-pattern" aria-label="Permalink to &quot;The catalogue pattern&quot;">​</a></h3><p><code>/missions</code>, <code>/fleet</code>, <code>/programs</code> and <code>/missions/launches</code> share one page pattern, so what you learn on one works on the others:</p><ul><li><strong>Search</strong> box at the top, then the <strong><code>FILTERS</code> chip</strong> with the total.</li><li><strong>Era strip</strong> — nine tiles, First Steps (1957–1961) · Space Race · Lunar Era · First Stations · Shuttle &amp; Mir · ISS Assembly · Commercial Era · Lunar Return · Mars Era (2030+). Each tile carries a flagship photo, its count and the agency dots of what is in it; click one to show that era only (the line under the filters reads <code>Showing: &lt;era&gt; (n)</code>); arrow keys move between tiles. An era with nothing in it is dimmed and cannot be selected. Programs are placed by start year, launches by launch year.</li><li><strong>Agency chips</strong> — one colour per agency (dot, name, count), the same colour as the dot on the era tile and the bar on each card. &quot;Show all N&quot; opens the rest.</li><li><strong>Toolbar</strong> — the count and what is showing, <strong>SORT</strong>, and <strong>GRID / LIST</strong>.</li><li><strong>Cards</strong> — a photo, the name and year, one line per agency (a bar in its colour, then the name), a status pill and a one-line story.</li></ul><p><strong>What you can do on <code>/missions</code></strong>:</p><ul><li><strong>Next launches</strong> — the strip at the top shows the next launches from the launch calendar; <strong>ALL LAUNCHES</strong> opens <code>/missions/launches</code>.</li><li><strong><code>FILTERS</code> chip</strong> — expands the destination, status and crew pills (collapsed by default for a clean grid; the era strip and agency chips are always visible). When you land via a deep link with filter params (<code>?dest=MARS</code>, <code>?from=1969</code>, etc.) the strip auto-expands so you can see what&#39;s active.</li><li><strong>Filter</strong> by destination / agency / status.</li><li><strong>Click any card</strong> — opens a detail panel with OVERVIEW · FLIGHT · GALLERY · SCIENCE tabs.</li><li><strong>▶ FLY THIS MISSION</strong> from any panel — jumps to <code>/fly?mission=&lt;id&gt;</code>.</li><li><strong>FLIGHT tab</strong> carries per-mission ∆v ledgers, with caveat banners (RECONSTRUCTED / SPARSE / UNKNOWN) when the public data is incomplete.</li></ul><p><a href="screenshots/mission-panel.png"><img src="'+m+'" alt="Mission detail"></a></p><p><strong>Launches</strong> (<code>/missions/launches</code>) opens as a <strong>month-grouped list</strong> (soonest first; GRID is the other view) of the upcoming-launch calendar from Launch Library 2 and the historic launches from GCAT, with a <strong>VIA LL2</strong> provenance chip on every row. The era strip counts launches by launch year; the chips are launch providers.</p><p><a href="screenshots/18-launches-catalogue.png"><img src="'+y+'" alt="Launches"></a></p><h3 id="programs-·-programs" tabindex="-1">Programs · <code>/programs</code> <a class="header-anchor" href="#programs-·-programs" aria-label="Permalink to &quot;Programs · `/programs`&quot;">​</a></h3><p>42 programs — Apollo, Artemis, Ariane, Buran, Cassini, Chandrayaan, the commercial stations, Project Kuiper and more. The head of the page is a row of mission patches; the rest is the catalogue pattern above. A program page lists its missions, hardware and milestones.</p><p><a href="screenshots/17-programs-catalogue.png"><img src="'+f+'" alt="Programs"></a></p><h3 id="spaceflight-fleet-·-fleet" tabindex="-1">Spaceflight Fleet · <code>/fleet</code> <a class="header-anchor" href="#spaceflight-fleet-·-fleet" aria-label="Permalink to &quot;Spaceflight Fleet · `/fleet`&quot;">​</a></h3><p>299 entries in 12 categories — crewed spacecraft, cargo spacecraft, launchers, engines, landers, orbiters, rovers, observatories, stations, space suits, constellations, launch sites — each cross-linked to the missions and sites that used it.</p><p><a href="screenshots/16-fleet-catalogue.png"><img src="'+b+'" alt="Fleet"></a></p><ul><li><strong>GRID / LIST / LINE-UP</strong> — LINE-UP compares the launchers, or the capsules and spacecraft, at scale (<code>?view=lineup&amp;kind=launchers|spacecraft</code>); while it is on, the FILTERS chip is disabled.</li><li><strong>Click any card</strong> for the detail panel: GALLERY, <strong>ANATOMY</strong> (198 hand-generated cutaways: 158 spacecraft and 40 launcher sketches), TECHNICAL, LEARN, and one <strong>MISSIONS</strong> tab that lists every mission the craft flew, oldest first. <code>/fleet/&lt;id&gt;</code> shows the same list.</li></ul><hr><h2 id="earth-orbit-·-earth" tabindex="-1">Earth Orbit · <code>/earth</code> <a class="header-anchor" href="#earth-orbit-·-earth" aria-label="Permalink to &quot;Earth Orbit · `/earth`&quot;">​</a></h2><p>Logarithmic radial scale showing the infrastructure that surrounds Earth: ISS, Tiangong, Hubble, JWST, Gaia, Chandra, XMM-Newton, LRO + the four GNSS constellations (GPS, Galileo, GLONASS, BeiDou) + GEO ring.</p><p><a href="screenshots/05-earth.png"><img src="'+w+'" alt="Earth orbit"></a></p><p><strong>What you can do</strong>:</p><ul><li><strong>Drag</strong> to orbit Earth, <strong>scroll</strong> to zoom in toward the surface (the altitude readout at the bottom right follows); objects sit at their real inclinations. <strong>SPIN</strong> and <strong>RESET VIEW</strong> are in the top row.</li><li><strong>Click any object</strong> — detail panel with launch / period / inclination / crew / capability fields, plus GALLERY · LEARN · SCIENCE tabs.</li><li><strong>Layer chips</strong> (top row) toggle SURFACE · LOW (the surface detail level), LAUNCHPADS, MUSEUMS, OBSERVATORIES and ORBITERS.</li><li><strong>INDEX</strong> (left edge) lists every object; <strong>CENTER ON MY LOCATION</strong> turns the globe to where you are.</li><li><strong>ORBIT RULER</strong> (bottom left) lists the regimes from LEO to L2; each row draws its own band.</li></ul><p><strong>Lens layers</strong>: an <strong>atmosphere shell</strong> at the Kármán line (100 km) and <strong>ozone-hole indicators</strong> over both poles (Antarctic + Arctic depletion zones) appear when the Science Lens is on.</p><hr><h2 id="moon-map-·-moon" tabindex="-1">Moon Map · <code>/moon</code> <a class="header-anchor" href="#moon-map-·-moon" aria-label="Permalink to &quot;Moon Map · `/moon`&quot;">​</a></h2><p>21 surface sites across 7 nations (USA, USSR / Russia, Europe, China, India, Japan, Israel) plus 9 orbiters, plotted by latitude / longitude on a 3D Moon globe and a 2D equirectangular projection.</p><p><a href="screenshots/06-moon.png"><img src="'+v+'" alt="Moon map"></a></p><p><strong>What you can do</strong>:</p><ul><li><strong>3D Moon</strong> — drag to rotate, scroll to zoom, click any marker for site detail.</li><li><strong>2D map</strong> — equirectangular projection; click any marker for the same panel.</li><li><strong>Chips</strong> (top row) — SURFACE · LOW, ORBITERS, ORBITS and TRAVERSES.</li><li><strong>Site panel</strong> — OVERVIEW · GALLERY · STORY · LEARN, plus mission-specific fields (crew, surface time, samples returned, capability unlocked) and the actions STAND HERE (a panorama from the site), VIEW ROUTE, ZOOM IN and SHARE.</li><li><strong>Traverses</strong> — eight rover and astronaut routes (Apollo 15, 16 and 17, Lunokhod 1 and 2, Chang&#39;e 3 and 4, Chandrayaan-3) are drawn in the same style as the Mars rover routes: a colour ramp by distance driven from the lander, kilometre milestones, a ring at the landing site and a hover card (&quot;N km from landing&quot;). Six are real mapped tracks; the two nine-point outlines (Chang&#39;e 3, Chandrayaan-3) are labelled &quot;Approximate route&quot;.</li></ul><p><a href="screenshots/22-moon-traverse.png"><img src="'+k+'" alt="Apollo 17 on the Moon: landing site, panel and route"></a></p><p><strong>Lens layer</strong>: <strong>tidal-lock indicator</strong> marks the Moon&#39;s near-side hemisphere (always Earth-facing — the result of synchronous rotation) when the Science Lens is on.</p><hr><h2 id="mars-surface-map-·-mars" tabindex="-1">Mars Surface Map · <code>/mars</code> <a class="header-anchor" href="#mars-surface-map-·-mars" aria-label="Permalink to &quot;Mars Surface Map · `/mars`&quot;">​</a></h2><p>Equirectangular 2D map + 3D globe with surface-feature panels for landing sites, orbital probes, and major regions.</p><p><a href="screenshots/07-mars.png"><img src="'+S+'" alt="Mars map"></a></p><p><strong>What you can do</strong>:</p><ul><li><strong>3D / 2D toggle</strong> — drag the globe in 3D or scrub a flat equirectangular projection.</li><li><strong>16 surface sites</strong> (rovers, landers, sample-return) + <strong>11 orbital probes</strong>, each clickable for a detail panel.</li><li><strong>Rover traverse paths</strong> overlaid as cross-linked routes on Curiosity, Perseverance, Opportunity, Spirit and Zhurong (toggle them with the <strong>TRAVERSES</strong> chip).</li><li><strong>Layer chips</strong> (top row) — SURFACE · LOW, ORBITERS, ORBITS and TRAVERSES.</li><li><strong>Lens layer</strong>: an <strong>atmosphere shell</strong> at ~120 km marks Mars&#39;s effective atmospheric edge.</li><li><strong>Cross-links</strong>: Curiosity / Perseverance panels deep-link to <code>/missions/&lt;id&gt;</code> for the full mission record.</li></ul><hr><h2 id="iss-explorer-·-iss" tabindex="-1">ISS Explorer · <code>/iss</code> <a class="header-anchor" href="#iss-explorer-·-iss" aria-label="Permalink to &quot;ISS Explorer · `/iss`&quot;">​</a></h2><p>A full station-explorer route with raycast-pickable modules. 18 modules from every USOS + ROS module to visiting craft (Crew Dragon, Cargo Dragon, Soyuz MS, Cygnus, Progress MS, HTV-X, Starliner, Shenzhou, Tianzhou).</p><p><a href="screenshots/08-iss.png"><img src="'+A+'" alt="ISS Explorer"></a></p><p><strong>What you can do</strong>:</p><ul><li><strong>Drag</strong> to orbit the station; <strong>scroll</strong> to zoom; <strong>right-drag</strong> (or two-finger drag on touch) to pan.</li><li><strong>Click any module</strong> — opens a detail panel with <strong>OVERVIEW · GALLERY · TECHNICAL · ANATOMY · SCIENCE · LEARN</strong> tabs.</li><li><strong><code>MODULES</code> button</strong> — opens a drawer listing every module with its agency badge; click any entry to fly the camera to it.</li><li><strong><code>PAUSE SPIN</code> / <code>RESUME SPIN</code></strong> — freeze the station&#39;s rotation for clear screenshots.</li><li><strong><code>RESET</code></strong> — return to the default camera position.</li><li><strong>Solar arrays auto-track the Sun</strong> with a slow continuous rotation.</li><li><strong>Hover any module</strong> to see its name in a label sprite that tracks the module&#39;s projected screen position.</li></ul><p><strong>ANATOMY tab</strong>: hand-drawn schematics for 9 visiting spacecraft (Crew Dragon, Cargo Dragon, Cygnus, Soyuz MS, Progress MS, HTV-X, Starliner, Shenzhou, Tianzhou) — each shows hatch/docking, propulsion, life-support, and trunk layouts with named callouts.</p><p><strong>Orbit-regime banner</strong> at the top reads ALT · INCL · PERIOD with <strong>Why?</strong> popovers on each value (why ~400 km, why 51.6°, why ~92 min, why 16 sunrises a day).</p><p><strong>Lens layer</strong>: turn on the Science Lens for a <strong>microgravity axes overlay</strong> — three colour-keyed body axes (zenith/nadir, prograde/retrograde, port/starboard) drawn at the station centre with value labels at each arrow tip. The lens also opens an <strong>Orbital regime</strong> card (altitude, inclination, period, each with a Why? popover) and a <strong>Microgravity frame</strong> card that explains the three axes.</p><p><a href="screenshots/11-science-lens-iss.png"><img src="'+E+'" alt="Science Lens on the ISS"></a></p><hr><h2 id="tiangong-explorer-·-tiangong" tabindex="-1">Tiangong Explorer · <code>/tiangong</code> <a class="header-anchor" href="#tiangong-explorer-·-tiangong" aria-label="Permalink to &quot;Tiangong Explorer · `/tiangong`&quot;">​</a></h2><p>China&#39;s space station. Tianhe core + Wentian + Mengtian lab modules with sun-tracking gallium-arsenide arrays. Mirrors the <code>/iss</code> UX on the same shared <code>station-geometry</code> library.</p><p><a href="screenshots/09-tiangong.png"><img src="'+L+'" alt="Tiangong Explorer"></a></p><p><strong>What you can do</strong> (matches <code>/iss</code> interactions):</p><ul><li><strong>Click any module</strong> — detail panel with same tab set as <code>/iss</code>.</li><li><strong><code>MODULES</code> drawer</strong> with agency badges (CMSA · CASC).</li><li><strong>2D blueprint views</strong> — <code>2D ▾</code> switches between top, side, and front orthographic projections.</li><li><strong>Per-module hover labels</strong> + selected-module emissive pulse.</li><li><strong>Microgravity axes overlay</strong> lens-gated, same as <code>/iss</code>.</li></ul><p><strong>Visiting craft</strong> (Shenzhou crewed + Tianzhou cargo) render in their docked positions.</p><hr><h2 id="science-encyclopedia-·-science" tabindex="-1">Science Encyclopedia · <code>/science</code> <a class="header-anchor" href="#science-encyclopedia-·-science" aria-label="Permalink to &quot;Science Encyclopedia · `/science`&quot;">​</a></h2><p>The in-app explainer for every concept the simulator visualises. <strong>175 sections across 13 tabs</strong>, plus a Glossary and an editorial Space-101 narrative on the landing page.</p><p><a href="screenshots/10-science-landing.png"><img src="'+T+'" alt="Science encyclopedia landing"></a></p><p><strong>Tabs</strong>:</p><table tabindex="0"><thead><tr><th>Tab</th><th>What&#39;s in it</th><th>Sections</th></tr></thead><tbody><tr><td><strong>Scales &amp; Time</strong></td><td>AU, light-minute, ecliptic plane, J2000, sidereal vs synodic, reference frames, long-duration</td><td>7</td></tr><tr><td><strong>Planets</strong></td><td>The asteroid belt, the Kuiper belt, axial tilt and seasons, magnetic fields, lunar ice, how the Earth and Mars surface imagery layers work</td><td>14</td></tr><tr><td><strong>Exoplanets</strong></td><td>Detection methods (astrometry, direct imaging), atmospheres, the habitable zone, biosignatures, 51 Pegasi b</td><td>19</td></tr><tr><td><strong>Orbits</strong></td><td>Kepler&#39;s laws, vis-viva, semi-major axis, eccentricity, inclination, true anomaly, apsides, orbit regimes, Keplerian orbit, Lagrange points, Hill sphere</td><td>18</td></tr><tr><td><strong>Transfers</strong></td><td>Hohmann, Lambert problem, transfer ellipse, free return, gravity assist, conic sections, patched conics</td><td>8</td></tr><tr><td><strong>Porkchop</strong></td><td>What is a porkchop, departure axis, time-of-flight axis, ∆v heatmap, contour reading, viability</td><td>6</td></tr><tr><td><strong>Propulsion</strong></td><td>Tsiolkovsky equation, specific impulse, ∆v budget, C3 launch energy, V∞, Oberth effect</td><td>21</td></tr><tr><td><strong>Mission Phases</strong></td><td>Launch, trans-X injection, TCM, orbit insertion, EDL, EVA, MET, NRHO, mission types</td><td>29</td></tr><tr><td><strong>Space Stations</strong></td><td>Pressurised volume, node-module structure, solar-power budget, expedition cadence</td><td>4</td></tr><tr><td><strong>Life in Space</strong></td><td>Microgravity, radiation, IVA / EVA / lunar suits, long-duration life support, crew-health topics</td><td>26</td></tr><tr><td><strong>Observation</strong></td><td>Adaptive optics, black holes, coronagraphs, interferometry, space photography, spectroscopy, wormholes</td><td>14</td></tr><tr><td><strong>Cosmology</strong></td><td>The cosmic distance ladder, Laniakea and the Great Attractor, large-scale structure (the cosmic web)</td><td>3</td></tr><tr><td><strong>History</strong></td><td>Kepler 1609 · Newton 1687 · Tsiolkovsky 1903 · Goddard 1926 · Sputnik 1957 · Apollo 11 1969</td><td>6</td></tr></tbody></table><p><a href="screenshots/10-science-section.png"><img src="'+R+'" alt="Science section page"></a></p><p><strong>What you can do</strong>:</p><ul><li><strong>Click any tab</strong> in the left rail (sticky on desktop; folds to a single column on mobile).</li><li><strong>Right rail</strong> lists every section in the active tab; click to navigate, current section is highlighted.</li><li><strong>Cmd-K / Ctrl-K</strong> opens a search overlay across the entire encyclopedia — type a few letters of any concept (vis-viva, Hohmann, Kármán, etc.) and Enter navigates straight to the section.</li><li><strong>Cross-screen <code>?</code> chips</strong> — every numeric label across <code>/missions</code>, <code>/fly</code>, <code>/explore</code>, <code>/plan</code>, <code>/earth</code>, <code>/moon</code>, <code>/mars</code>, <code>/iss</code>, <code>/tiangong</code> carries a <code>?</code> chip that deep-links to the matching encyclopedia section.</li><li><strong>Why? popovers</strong> on individual values inline-explain the meaning without a route change.</li></ul><p><strong>Math</strong>: KaTeX server-rendered at build time per <a href="./../adr/ADR-034">ADR-034</a> — the client receives static HTML, no JavaScript math library is shipped. <strong>Diagrams</strong>: hand-coded SVGs in an engineering-blueprint style, with a fail-closed integrity gate on every build, per <a href="./../adr/ADR-035">ADR-035</a>.</p><hr><h2 id="essays-·-essays" tabindex="-1">Essays · <code>/essays</code> <a class="header-anchor" href="#essays-·-essays" aria-label="Permalink to &quot;Essays · `/essays`&quot;">​</a></h2><p><em>The Long View</em> — 13 essays in one story told in a spiral, grouped into themes such as &quot;Into the dark&quot; (how we find our way, move, and stay in touch where there are no roads). Each essay is a card with a diagram or picture; the essays&#39; outbound sources are in the <a href="#library-every-outbound-learn-link"><code>/library</code></a>.</p><h2 id="physics-lab-·-lab" tabindex="-1">Physics Lab · <code>/lab</code> <a class="header-anchor" href="#physics-lab-·-lab" aria-label="Permalink to &quot;Physics Lab · `/lab`&quot;">​</a></h2><p>First-principles physics, one goal at a time. Pick a <strong>goal</strong> (&quot;Launch a rocket&quot; is the first) and the lab opens a <strong>Notebook</strong> of calculator cards: each card is a formula with its inputs, a live figure on the blueprint grid, and the derivation in <code>/science</code>. <strong>Canvas</strong> is the other workspace: drag cards, wire one card&#39;s output to another&#39;s input, and promote a subgraph to a notebook. <strong>SHARE</strong> copies a link to the notebook; <strong>LAB REPORT</strong> and <strong>SHARE CARD</strong> export it; <strong>SAVE</strong> / <strong>LOAD</strong> keep a notebook as a <code>.orrlab</code> file. Every calculator also has its own page (<code>/lab/tsiolkovsky</code>).</p><h2 id="worlds-live-and-the-hubs" tabindex="-1">Worlds, Live and the hubs <a class="header-anchor" href="#worlds-live-and-the-hubs" aria-label="Permalink to &quot;Worlds, Live and the hubs&quot;">​</a></h2><p><code>/worlds</code> is the hub for the four worlds you can stand on (Earth, Moon, Mars and Venus; Venus is a globe with orbiters). <code>/live</code> shows the permanent ISS stream and launches happening now or soon, in-app, credited to the official channels. <code>/catalog</code> and <code>/learn</code> are the hubs of the CATALOG and LEARN menus.</p><hr><h2 id="gallery-·-gallery" tabindex="-1">Gallery · <code>/gallery</code> <a class="header-anchor" href="#gallery-·-gallery" aria-label="Permalink to &quot;Gallery · `/gallery`&quot;">​</a></h2><p>Orrery&#39;s visual collections — things to look at, download, and keep, free to use and credited in full. The hub has one strip per collection:</p><p><a href="screenshots/21-gallery.png"><img src="'+C+'" alt="Gallery hub"></a></p><ul><li><strong>Deep-sky</strong> (<code>/gallery/deep-sky</code>) — the universe&#39;s greatest hits as seen by Webb, Hubble and Chandra, with filter pills; each image opens in a viewer that fits one screen, with its facts, credit line and button always inside the window.</li><li><strong>Posters</strong> (<code>/posters</code>) — 27 original space posters, every era and agency from Sputnik to Starship; click any poster for the full-resolution file, ORRERY wordmark on every piece.</li><li><strong>Insignia</strong> (<code>/patches</code>) — the patches crews wore and programs flew; every one is an authentic public-domain NASA design, credited in full. Where a program never had a patch, or none exists under a free licence, the sourcing wall says so.</li></ul><hr><h2 id="provenance-pages" tabindex="-1">Provenance pages <a class="header-anchor" href="#provenance-pages" aria-label="Permalink to &quot;Provenance pages&quot;">​</a></h2><p>Long lists on these pages follow one rule: a list shows its <strong>first 10 rows</strong> and a <strong>Show all N</strong> chip; source headers stay open, so a <code>#src-&lt;id&gt;</code> link lands on the header with its first rows below it.</p><h3 id="credits-—-every-image-text-source-and-logo" tabindex="-1"><code>/credits</code> — every image, text source, and logo <a class="header-anchor" href="#credits-—-every-image-text-source-and-logo" aria-label="Permalink to &quot;`/credits` — every image, text source, and logo&quot;">​</a></h3><p>Public attribution page generated from <code>static/data/image-provenance.json</code> (auto-built by <code>scripts/build-image-provenance.ts</code>), <code>static/data/text-sources.json</code>, and <code>static/data/source-logos.json</code>. Every image in the app appears here with its license, source, and the original URL.</p><p><a href="screenshots/14-credits.png"><img src="'+x+'" alt="Credits page"></a></p><p>Image sourcing is <strong>agency-first</strong> per <a href="./../adr/ADR-046">ADR-046</a>: NASA / ESA / ISRO / CNSA / JAXA / KARI / Roscosmos before Wikimedia Commons fallback. Per-image provenance is AJV-validated and <strong>fail-closed</strong> in <code>validate-data</code> (per <a href="./../adr/ADR-047">ADR-047</a>) — adding an image without a provenance row breaks CI.</p><h3 id="library-—-every-outbound-learn-link" tabindex="-1"><code>/library</code> — every outbound LEARN link <a class="header-anchor" href="#library-—-every-outbound-learn-link" aria-label="Permalink to &quot;`/library` — every outbound LEARN link&quot;">​</a></h3><p>Bill-of-links across the entire app. Each external link the app exposes (in panel LEARN tabs, <code>/science</code> sections, the essays&#39; sources, <code>/credits</code> source URLs) appears here with its provenance row: source agency, language, freshness check date, status. Five blocks at the head name the data sources behind the app — Audio episodes, Launches data, Astrophysics data, Planetary models (NASA JPL) and Moon and Mars surface data — before the per-source tables.</p><p><a href="screenshots/15-library.png"><img src="'+P+'" alt="Library page"></a></p><p>Link policy is <strong>agency-first, native-language priority</strong> per <a href="./../adr/ADR-051">ADR-051</a>: for non-US entities, the operator&#39;s own page (in their own language) wins over the NASA mirror. Roscosmos before Wikipedia. ISRO before press releases. The link-checker (<code>scripts/check-learn-links.ts</code>) is chained into <code>npm run fetch</code> so dead links are flagged before they ship.</p><hr><h2 id="mobile" tabindex="-1">Mobile <a class="header-anchor" href="#mobile" aria-label="Permalink to &quot;Mobile&quot;">​</a></h2><p>Every screen works at 375 px width. Touch targets are 44×44 px minimum. Bottom-sheet panels swipe down to dismiss. The porkchop magnifier loupe is mobile-only (long-press on the plot).</p><p>The PWA manifest is shipped — install Orrery as a standalone app via the browser menu (Chrome / Safari / Firefox all support this; the in-app install nag is intentionally suppressed per <a href="./../adr/ADR-029">ADR-029</a>).</p><hr><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><ul><li><strong>Analytics</strong>: aggregate only, self-hosted (<a href="https://umami.is/" target="_blank" rel="noreferrer">Umami</a>) — page-view counts per route and a few structured events, never anything that identifies you. You can switch it off on <a href="https://www.orrerylearn.com/privacy" target="_blank" rel="noreferrer"><code>/privacy</code></a>.</li><li><strong>Error tracking</strong>: unhandled JavaScript errors only, to a self-hosted GlitchTip; no PII, no session replay.</li><li><strong>Cookies</strong>: three functional cookies, each written only on a deliberate action — <code>orrery_locale</code> (when you click a locale chip), <code>orrery_tour</code> (Curator Tour resume position) and <code>orrery_analytics_optout</code> (when you opt out).</li><li>A few device-local <code>localStorage</code> keys hold rendering preferences (quality tier, debug mode, offline downloads); settings, no PII.</li><li>No third-party fonts, images, or scripts loaded at runtime — every asset is bundled at build time per <a href="./../adr/ADR-016">ADR-016</a>.</li></ul><p>The state that persists across sessions is what&#39;s in the URL (<code>?lang=</code>, <code>?mission=</code>, <code>?dest=</code>, etc.), the cookies and keys above, and the service-worker cache (so the app works offline after the first load). The full list, with the ADR behind each item, is in the README&#39;s <a href="https://github.com/chipi/orrery#privacy" target="_blank" rel="noreferrer">Privacy</a> section.</p><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>The 3D scene is empty.</strong> Most likely WebGL is disabled in your browser. Try a different browser or enable WebGL.</p><p><strong>The 3D scene drops to a list view.</strong> <code>/iss</code> and <code>/tiangong</code> auto-fall back to a module list when measured FPS drops below 20 (typically on integrated GPUs running with software rasterisation). Reload — sometimes the first paint is slower than later runs.</p><p><strong>Images don&#39;t load.</strong> Either you&#39;re offline before the service worker has cached them, or the agency image API is rate-limiting. Reload after a minute; cached images persist.</p><p><strong>A translation looks weird.</strong> All 14 locales now ship at 100% UI parity AND full editorial overlay coverage as of v0.6.x. If a string reads off, file an issue; the <a href="./i18n-style-guide">i18n style guide</a> is the binding source of truth per <a href="./../adr/ADR-033">ADR-033</a>.</p><p><strong>Missions render outside the camera.</strong> Moon missions render in a dedicated cislunar view at true Earth-Moon scale (ADR-058); interplanetary missions render heliocentrically with an auto-zoom that pulls in at departure and arrival. Drag to pan; scroll to zoom — manual zoom wins over auto-zoom until the next phase transition.</p><p><strong>A linked external page is dead.</strong> File an issue or PR — the provenance manifest at <code>static/data/link-provenance.json</code> is the source of truth and welcomes corrections. Run <code>npm run check-learn-links -- --update</code> to regenerate the freshness gates.</p><hr><h2 id="where-to-next" tabindex="-1">Where to next <a class="header-anchor" href="#where-to-next" aria-label="Permalink to &quot;Where to next&quot;">​</a></h2><ul><li><strong><a href="./../concept/02_Project_Concept">02 Project Concept</a></strong> — the complete synthesis of what Orrery is.</li><li><strong><a href="./../concept/03_Data_Catalog">03 Data Catalog</a></strong> — every constant, every source, mission schema, credit format.</li><li><strong><a href="./i18n-style-guide">i18n style guide</a></strong> — the binding glossary for translators.</li><li><strong><code>AGENTS.md</code></strong> in the repo root — engineering constraints if you&#39;re contributing code (visible on GitHub: <a href="https://github.com/chipi/orrery/blob/main/AGENTS.md" target="_blank" rel="noreferrer">https://github.com/chipi/orrery/blob/main/AGENTS.md</a>). Tool-specific overlays for Claude Code and Cursor live in <code>CLAUDE.md</code> and <code>.cursor/rules/orrery.mdc</code> respectively, both of which point back at this file.</li><li><strong>In-app</strong>: open the <code>/science</code> encyclopedia and read the <strong>Space-101</strong> narrative on the landing page — an 8-chapter primer that takes you from &quot;what is an orbit&quot; to &quot;how a Hohmann transfer works&quot; with no jargon.</li></ul>',162)])])}const U=t(I,[["render",D]]);export{G as __pageData,U as default};
